#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
if [[ "${1:-}" != --verify ]]; then
  [[ "$(hostname -s)" == desifaces-gpu ]] || { echo 'FAIL: production host required'; exit 1; }
fi
DEPLOY_BUNDLE_DIR="$(mktemp -d /tmp/desifaces-ending-bundle-XXXXXX)"
export DEPLOY_BUNDLE_DIR
trap 'rm -rf "$DEPLOY_BUNDLE_DIR"' EXIT
python3 - "$DEPLOY_BUNDLE_DIR" <<'PYBUNDLE'
import base64, hashlib, json, pathlib, sys, zlib
payload=json.loads(zlib.decompress(base64.b64decode("")))
for name,entry in payload.items():
    data=base64.b64decode(entry['data'])
    assert hashlib.sha256(data).hexdigest()==entry['sha256'], 'bundle corruption'
    (pathlib.Path(sys.argv[1])/name).write_bytes(data)
print('OFFLINE_BUNDLE_INTEGRITY=PASS')
PYBUNDLE
if [[ "${1:-}" == --verify ]]; then
  bash -n "$DEPLOY_BUNDLE_DIR/deploy.sh"
  python3 -m py_compile "$DEPLOY_BUNDLE_DIR/audit.py"
  echo 'OFFLINE_BUNDLE_SYNTAX=PASS'
  exit 0
fi
if [[ "${1:-}" == --audit ]]; then
  docker exec -i df-svc-fusion-extension-stitch-worker python - "${2:?Job ID required}" < "$DEPLOY_BUNDLE_DIR/audit.py"
  exit 0
fi
bundle_read(){
  python3 - "$DEPLOY_BUNDLE_DIR/assets.json" "$1" <<'PYASSET'
import json, sys
prefix='repos/prasshanthshankar-afk/desifaces_backend/contents/'
assert sys.argv[2].startswith(prefix), 'unexpected asset request'
print(json.load(open(sys.argv[1]))[sys.argv[2][len(prefix):]])
PYASSET
}
export -f bundle_read
bash "$DEPLOY_BUNDLE_DIR/deploy.sh" d55b8b3ee40be7f327fae43739dd6c90e06517ce
docker exec -i df-svc-fusion-extension-stitch-worker python - < "$DEPLOY_BUNDLE_DIR/audit.py"
